import React, { useState, useEffect } from 'react';
import { Helmet } from 'react-helmet';
import Header from '../../components/ui/Header';
import Sidebar from '../../components/ui/Sidebar';
import WelcomeCard from './components/WelcomeCard';
import StatsOverview from './components/StatsOverview';
import QuickActions from './components/QuickActions';
import RecentActivity from './components/RecentActivity';
import HealthInsights from './components/HealthInsights';
import NotificationCenter from './components/NotificationCenter';
import Icon from '../../components/AppIcon';
import Button from '../../components/ui/Button';

const IntelligentDashboard = () => {
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [userRole, setUserRole] = useState('practitioner'); // practitioner, patient, admin
  const [currentTime, setCurrentTime] = useState('');
  const [dashboardData, setDashboardData] = useState({
    stats: {},
    activities: [],
    insights: {},
    notifications: []
  });

  // Mock user data
  const userData = {
    practitioner: {
      name: 'Dr. Priya Sharma',
      title: 'Senior Ayurvedic Practitioner',
      avatar: 'https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=150&h=150&fit=crop&crop=face'
    },
    patient: {
      name: 'Rajesh Kumar',
      title: 'Wellness Journey Member',
      avatar: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&h=150&fit=crop&crop=face'
    },
    admin: {
      name: 'Admin User',
      title: 'System Administrator',
      avatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&h=150&fit=crop&crop=face'
    }
  };

  const currentUser = userData?.[userRole];

  useEffect(() => {
    // Update current time
    const updateTime = () => {
      const now = new Date();
      setCurrentTime(now?.toLocaleString('en-US', {
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      }));
    };

    updateTime();
    const timeInterval = setInterval(updateTime, 60000); // Update every minute

    // Simulate loading dashboard data
    const loadDashboardData = () => {
      setDashboardData({
        stats: {
          activePatients: 24,
          dietPlans: 156,
          successRate: 89,
          pendingReviews: 7,
          daysOnPlan: 45,
          complianceRate: 92,
          weightProgress: -3.2,
          energyLevel: 8.5,
          totalUsers: 1247,
          activeSessions: 89,
          systemHealth: 98.5,
          supportTickets: 12
        },
        activities: [],
        insights: {},
        notifications: []
      });
    };

    loadDashboardData();

    return () => {
      clearInterval(timeInterval);
    };
  }, []);

  const toggleSidebar = () => {
    setSidebarCollapsed(!sidebarCollapsed);
  };

  const switchRole = (role) => {
    setUserRole(role);
  };

  return (
    <>
      <Helmet>
        <title>Intelligent Dashboard - AyurDiet Pro</title>
        <meta name="description" content="Personalized command center for Ayurvedic wellness management with role-based insights and analytics." />
      </Helmet>
      <div className="min-h-screen bg-background">
        {/* Header */}
        <Header />

        <div className="flex">
          {/* Sidebar */}
          <Sidebar 
            isCollapsed={sidebarCollapsed}
            onToggleCollapse={toggleSidebar}
          />

          {/* Main Content */}
          <main className={`flex-1 transition-all duration-300 ${
            sidebarCollapsed ? 'ml-16' : 'ml-64'
          } p-6 space-y-8`}>
            
            {/* Role Switcher (Demo purposes) */}
            <div className="flex justify-end mb-4">
              <div className="flex items-center space-x-2 bg-surface rounded-lg p-1">
                <span className="text-sm text-text-secondary px-3">Demo Role:</span>
                {['practitioner', 'patient', 'admin']?.map((role) => (
                  <Button
                    key={role}
                    variant={userRole === role ? 'default' : 'ghost'}
                    size="sm"
                    onClick={() => switchRole(role)}
                    className="capitalize"
                  >
                    {role}
                  </Button>
                ))}
              </div>
            </div>

            {/* Welcome Section */}
            <WelcomeCard 
              userRole={userRole}
              userName={currentUser?.name}
              currentTime={currentTime}
            />

            {/* Stats Overview */}
            <StatsOverview 
              userRole={userRole}
              stats={dashboardData?.stats}
            />

            {/* Main Dashboard Grid */}
            <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
              
              {/* Left Column - Quick Actions & Recent Activity */}
              <div className="xl:col-span-2 space-y-8">
                <QuickActions userRole={userRole} />
                <RecentActivity 
                  userRole={userRole}
                  activities={dashboardData?.activities}
                />
              </div>

              {/* Right Column - Notifications */}
              <div className="xl:col-span-1">
                <NotificationCenter 
                  userRole={userRole}
                  notifications={dashboardData?.notifications}
                />
              </div>
            </div>

            {/* Health Insights Section */}
            <HealthInsights 
              userRole={userRole}
              insights={dashboardData?.insights}
            />

            {/* Footer */}
            <footer className="border-t border-border pt-8 mt-12">
              <div className="flex flex-col md:flex-row items-center justify-between">
                <div className="flex items-center space-x-4 mb-4 md:mb-0">
                  <div className="w-8 h-8 bg-brand-gradient rounded-lg flex items-center justify-center">
                    <Icon name="Leaf" size={16} color="white" />
                  </div>
                  <div>
                    <div className="font-heading font-semibold text-brand-primary">
                      AyurDiet Pro
                    </div>
                    <div className="text-xs text-text-secondary">
                      Ancient Wisdom, Modern Intelligence
                    </div>
                  </div>
                </div>
                
                <div className="flex items-center space-x-6 text-sm text-text-secondary">
                  <span>© {new Date()?.getFullYear()} AyurDiet Pro. All rights reserved.</span>
                  <div className="flex items-center space-x-4">
                    <a href="#" className="hover:text-text-primary transition-colors">Privacy</a>
                    <a href="#" className="hover:text-text-primary transition-colors">Terms</a>
                    <a href="#" className="hover:text-text-primary transition-colors">Support</a>
                  </div>
                </div>
              </div>
            </footer>
          </main>
        </div>
      </div>
    </>
  );
};

export default IntelligentDashboard;