import React from 'react';
import Icon from '../../../components/AppIcon';

const ProgressIndicator = ({ currentStep, totalSteps, steps }) => {
  const progressPercentage = (currentStep / totalSteps) * 100;

  return (
    <div className="w-full bg-surface rounded-lg p-6 mb-6 card-elevated">
      <div className="flex items-center justify-between mb-4">
        <h2 className="font-heading font-semibold text-lg text-text-primary">
          Prakriti Assessment Progress
        </h2>
        <span className="text-sm text-text-secondary">
          Step {currentStep} of {totalSteps}
        </span>
      </div>
      {/* Progress Bar */}
      <div className="relative w-full h-2 bg-muted rounded-full mb-6">
        <div 
          className="absolute top-0 left-0 h-full bg-brand-gradient rounded-full transition-all duration-500 ease-smooth"
          style={{ width: `${progressPercentage}%` }}
        />
      </div>
      {/* Step Indicators */}
      <div className="flex justify-between items-center">
        {steps?.map((step, index) => {
          const stepNumber = index + 1;
          const isCompleted = stepNumber < currentStep;
          const isCurrent = stepNumber === currentStep;
          
          return (
            <div key={step?.id} className="flex flex-col items-center space-y-2">
              <div className={`w-8 h-8 rounded-full flex items-center justify-center transition-smooth ${
                isCompleted 
                  ? 'bg-success text-success-foreground' 
                  : isCurrent 
                    ? 'bg-primary text-primary-foreground' 
                    : 'bg-muted text-text-secondary'
              }`}>
                {isCompleted ? (
                  <Icon name="Check" size={16} />
                ) : (
                  <span className="text-sm font-medium">{stepNumber}</span>
                )}
              </div>
              <span className={`text-xs text-center max-w-16 ${
                isCurrent ? 'text-text-primary font-medium' : 'text-text-secondary'
              }`}>
                {step?.title}
              </span>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default ProgressIndicator;