import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Header from '../../components/ui/Header';
import ProgressIndicator from './components/ProgressIndicator';
import PersonalInfoForm from './components/PersonalInfoForm';
import QuestionCard from './components/QuestionCard';
import ConstitutionResult from './components/ConstitutionResult';
import Button from '../../components/ui/Button';
import Icon from '../../components/AppIcon';

const PatientProfileBuilder = () => {
  const navigate = useNavigate();
  const [currentStep, setCurrentStep] = useState(1);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [answers, setAnswers] = useState({});
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    age: '',
    gender: '',
    height: '',
    weight: '',
    activityLevel: '',
    healthGoals: [],
    medications: '',
    allergies: '',
    termsAccepted: false
  });
  const [errors, setErrors] = useState({});
  const [assessmentResult, setAssessmentResult] = useState(null);

  const steps = [
    { id: 1, title: 'Personal Info' },
    { id: 2, title: 'Assessment' },
    { id: 3, title: 'Results' }
  ];

  const assessmentQuestions = [
    {
      id: 'physical_build',
      title: 'How would you describe your physical build?',
      description: 'Consider your natural body frame and how you tend to gain or lose weight.',
      icon: 'User',
      sanskritTerm: 'Sharira Prakriti',
      sanskritMeaning: 'Physical constitution',
      options: [
        {
          id: 'vata_build',
          text: 'Thin, light frame',
          description: 'Naturally slender, find it hard to gain weight, prominent joints'
        },
        {
          id: 'pitta_build',
          text: 'Medium, athletic build',
          description: 'Moderate weight, well-proportioned, gain/lose weight easily'
        },
        {
          id: 'kapha_build',
          text: 'Larger, solid frame',
          description: 'Naturally heavier build, gain weight easily, strong bones'
        }
      ]
    },
    {
      id: 'skin_hair',
      title: 'What best describes your skin and hair?',
      description: 'Think about your natural skin texture, hair type, and how they respond to weather.',
      icon: 'Sparkles',
      sanskritTerm: 'Tvak Prakriti',
      sanskritMeaning: 'Skin constitution',
      options: [
        {
          id: 'vata_skin',
          text: 'Dry, thin skin; dry, frizzy hair',
          description: 'Skin tends to be rough, hair is coarse and tends to tangle'
        },
        {
          id: 'pitta_skin',
          text: 'Warm, oily skin; fine, straight hair',
          description: 'Skin is soft and warm, hair is silky and may gray early'
        },
        {
          id: 'kapha_skin',
          text: 'Cool, moist skin; thick, wavy hair',
          description: 'Skin is smooth and cool, hair is abundant and lustrous'
        }
      ]
    },
    {
      id: 'digestion',
      title: 'How is your digestion and appetite?',
      description: 'Consider your natural hunger patterns, digestion strength, and food preferences.',
      icon: 'Apple',
      sanskritTerm: 'Agni Prakriti',
      sanskritMeaning: 'Digestive fire constitution',
      options: [
        {
          id: 'vata_digestion',
          text: 'Variable appetite, gas and bloating',
          description: 'Sometimes very hungry, sometimes not, prone to digestive irregularities'
        },
        {
          id: 'pitta_digestion',
          text: 'Strong appetite, gets irritable when hungry',
          description: 'Regular strong hunger, good digestion, prefers cool foods'
        },
        {
          id: 'kapha_digestion',
          text: 'Slow, steady appetite, feels heavy after eating',
          description: 'Can skip meals easily, slow digestion, prefers warm spicy foods'
        }
      ]
    },
    {
      id: 'sleep_energy',
      title: 'What are your sleep and energy patterns?',
      description: 'Think about your natural sleep needs, energy levels throughout the day.',
      icon: 'Moon',
      sanskritTerm: 'Nidra Prakriti',
      sanskritMeaning: 'Sleep constitution',
      options: [
        {
          id: 'vata_sleep',
          text: 'Light sleeper, variable energy',
          description: 'Difficulty falling asleep, wake easily, energy comes in bursts'
        },
        {
          id: 'pitta_sleep',
          text: 'Moderate sleep, intense energy',
          description: 'Fall asleep easily, moderate sleep needs, sustained energy'
        },
        {
          id: 'kapha_sleep',
          text: 'Deep sleeper, steady energy',
          description: 'Love long sleep, hard to wake up, slow but steady energy'
        }
      ]
    },
    {
      id: 'mental_emotional',
      title: 'How would you describe your mental and emotional tendencies?',
      description: 'Consider your natural personality, how you handle stress, and learning style.',
      icon: 'Brain',
      sanskritTerm: 'Manas Prakriti',
      sanskritMeaning: 'Mental constitution',
      options: [
        {
          id: 'vata_mental',
          text: 'Creative, quick thinking, anxious under stress',
          description: 'Learn quickly but forget easily, creative, worry-prone'
        },
        {
          id: 'pitta_mental',
          text: 'Focused, organized, irritable under stress',
          description: 'Sharp intellect, good memory, can be critical or impatient'
        },
        {
          id: 'kapha_mental',
          text: 'Calm, steady, withdrawn under stress',
          description: 'Learn slowly but retain well, patient, can be stubborn'
        }
      ]
    }
  ];

  useEffect(() => {
    // Save progress to localStorage
    const progressData = {
      currentStep,
      currentQuestionIndex,
      answers,
      formData,
      timestamp: new Date()?.toISOString()
    };
    localStorage.setItem('prakriti_assessment_progress', JSON.stringify(progressData));
  }, [currentStep, currentQuestionIndex, answers, formData]);

  useEffect(() => {
    // Load saved progress on component mount
    const savedProgress = localStorage.getItem('prakriti_assessment_progress');
    if (savedProgress) {
      try {
        const data = JSON.parse(savedProgress);
        // Only restore if saved within last 24 hours
        const savedTime = new Date(data.timestamp);
        const now = new Date();
        const hoursDiff = (now - savedTime) / (1000 * 60 * 60);
        
        if (hoursDiff < 24) {
          setCurrentStep(data?.currentStep || 1);
          setCurrentQuestionIndex(data?.currentQuestionIndex || 0);
          setAnswers(data?.answers || {});
          setFormData(data?.formData || formData);
        }
      } catch (error) {
        console.error('Error loading saved progress:', error);
      }
    }
  }, []);

  const validatePersonalInfo = () => {
    const newErrors = {};
    
    if (!formData?.fullName?.trim()) newErrors.fullName = 'Full name is required';
    if (!formData?.email?.trim()) newErrors.email = 'Email is required';
    else if (!/\S+@\S+\.\S+/?.test(formData?.email)) newErrors.email = 'Invalid email format';
    if (!formData?.age) newErrors.age = 'Age is required';
    if (!formData?.gender) newErrors.gender = 'Gender is required';
    if (!formData?.activityLevel) newErrors.activityLevel = 'Activity level is required';
    if (formData?.healthGoals?.length === 0) newErrors.healthGoals = 'At least one health goal is required';
    if (!formData?.termsAccepted) newErrors.termsAccepted = 'You must accept the terms to continue';
    
    setErrors(newErrors);
    return Object.keys(newErrors)?.length === 0;
  };

  const calculateConstitution = () => {
    const doshaScores = { vata: 0, pitta: 0, kapha: 0 };
    
    Object.values(answers)?.forEach(answer => {
      if (answer?.includes('vata')) doshaScores.vata++;
      else if (answer?.includes('pitta')) doshaScores.pitta++;
      else if (answer?.includes('kapha')) doshaScores.kapha++;
    });

    const sortedDoshas = Object.entries(doshaScores)?.sort(([,a], [,b]) => b - a)?.map(([dosha]) => dosha);

    const primaryDosha = sortedDoshas?.[0];
    const secondaryDosha = doshaScores?.[sortedDoshas?.[1]] > 0 ? sortedDoshas?.[1] : null;
    
    const constitution = secondaryDosha 
      ? `${primaryDosha?.charAt(0)?.toUpperCase() + primaryDosha?.slice(1)}-${secondaryDosha?.charAt(0)?.toUpperCase() + secondaryDosha?.slice(1)}`
      : primaryDosha?.charAt(0)?.toUpperCase() + primaryDosha?.slice(1);

    let characteristics = getCharacteristics(primaryDosha, secondaryDosha);
    const recommendations = getRecommendations(primaryDosha, secondaryDosha);

    return {
      primaryDosha: primaryDosha?.charAt(0)?.toUpperCase() + primaryDosha?.slice(1),
      secondaryDosha: secondaryDosha ? secondaryDosha?.charAt(0)?.toUpperCase() + secondaryDosha?.slice(1) : null,
      constitution,
      characteristics,
      recommendations,
      scores: doshaScores
    };
  };

  const getCharacteristics = (primary, secondary) => {
    const allCharacteristics = {
      vata: [
        { trait: 'Creative and Imaginative', description: 'Natural ability to think outside the box' },
        { trait: 'Quick and Agile', description: 'Fast learner with quick reflexes' },
        { trait: 'Enthusiastic', description: 'Brings energy and excitement to projects' },
        { trait: 'Flexible and Adaptable', description: 'Easily adjusts to new situations' }
      ],
      pitta: [
        { trait: 'Natural Leader', description: 'Takes charge and organizes effectively' },
        { trait: 'Sharp Intellect', description: 'Excellent analytical and problem-solving skills' },
        { trait: 'Goal-Oriented', description: 'Focused on achieving objectives' },
        { trait: 'Confident and Decisive', description: 'Makes decisions quickly and stands by them' }
      ],
      kapha: [
        { trait: 'Calm and Stable', description: 'Provides grounding presence in stressful situations' },
        { trait: 'Loyal and Supportive', description: 'Reliable friend and team member' },
        { trait: 'Patient and Persistent', description: 'Sees projects through to completion' },
        { trait: 'Nurturing Nature', description: 'Naturally caring and protective of others' }
      ]
    };

    let characteristics = [...allCharacteristics?.[primary]];
    if (secondary && allCharacteristics?.[secondary]) {
      characteristics = characteristics?.concat(allCharacteristics?.[secondary]?.slice(0, 2));
    }
    
    return characteristics?.slice(0, 6);
  };

  const getRecommendations = (primary, secondary) => {
    const allRecommendations = {
      vata: [
        {
          category: 'Diet',
          icon: 'Apple',
          advice: 'Favor warm, cooked foods with healthy fats. Include sweet, sour, and salty tastes. Eat regular meals and avoid cold, dry foods.'
        },
        {
          category: 'Lifestyle',
          icon: 'Clock',
          advice: 'Maintain regular routines for meals and sleep. Practice calming activities like yoga and meditation. Stay warm and avoid excessive travel.'
        }
      ],
      pitta: [
        {
          category: 'Diet',
          icon: 'Apple',
          advice: 'Choose cooling foods like fresh fruits and vegetables. Favor sweet, bitter, and astringent tastes. Avoid spicy, oily, and acidic foods.'
        },
        {
          category: 'Lifestyle',
          icon: 'Sun',
          advice: 'Avoid excessive heat and sun exposure. Practice moderate exercise. Take time for relaxation and avoid overworking.'
        }
      ],
      kapha: [
        {
          category: 'Diet',
          icon: 'Apple',
          advice: 'Choose light, warm, and spicy foods. Favor pungent, bitter, and astringent tastes. Limit dairy, sweets, and heavy foods.'
        },
        {
          category: 'Lifestyle',
          icon: 'Activity',
          advice: 'Engage in regular vigorous exercise. Wake up early and stay active. Seek variety and stimulation in daily activities.'
        }
      ]
    };

    let recommendations = [...allRecommendations?.[primary]];
    if (secondary && allRecommendations?.[secondary]) {
      recommendations?.push(allRecommendations?.[secondary]?.[0]);
    }
    
    return recommendations;
  };

  const handlePersonalInfoNext = () => {
    if (validatePersonalInfo()) {
      setCurrentStep(2);
    }
  };

  const handleAnswerSelect = (answerId) => {
    const questionId = assessmentQuestions?.[currentQuestionIndex]?.id;
    setAnswers({ ...answers, [questionId]: answerId });
  };

  const handleQuestionNext = () => {
    if (currentQuestionIndex < assessmentQuestions?.length - 1) {
      setCurrentQuestionIndex(currentQuestionIndex + 1);
    } else {
      // Complete assessment
      const result = calculateConstitution();
      setAssessmentResult(result);
      setCurrentStep(3);
    }
  };

  const handleQuestionPrevious = () => {
    if (currentQuestionIndex > 0) {
      setCurrentQuestionIndex(currentQuestionIndex - 1);
    } else {
      setCurrentStep(1);
    }
  };

  const handleStartDietGeneration = () => {
    // Save assessment result to localStorage for use in diet generator
    localStorage.setItem('patient_constitution', JSON.stringify({
      ...assessmentResult,
      personalInfo: formData,
      completedAt: new Date()?.toISOString()
    }));
    
    navigate('/ai-diet-generator');
  };

  const handleRetakeAssessment = () => {
    setCurrentStep(1);
    setCurrentQuestionIndex(0);
    setAnswers({});
    setAssessmentResult(null);
    localStorage.removeItem('prakriti_assessment_progress');
  };

  const currentQuestion = assessmentQuestions?.[currentQuestionIndex];
  const selectedAnswer = answers?.[currentQuestion?.id];
  const canProceedQuestion = selectedAnswer !== undefined;

  return (
    <div className="min-h-screen bg-background">
      <Header />
      <div className="max-w-4xl mx-auto px-4 py-8">
        {/* Page Header */}
        <div className="text-center mb-8">
          <div className="flex items-center justify-center space-x-3 mb-4">
            <div className="w-12 h-12 bg-brand-gradient rounded-lg flex items-center justify-center">
              <Icon name="UserPlus" size={24} color="white" />
            </div>
            <div>
              <h1 className="font-heading font-bold text-3xl text-text-primary">
                Patient Profile Builder
              </h1>
              <p className="font-accent text-text-secondary">
                Discover your unique Ayurvedic constitution
              </p>
            </div>
          </div>
          <p className="text-text-secondary max-w-2xl mx-auto leading-relaxed">
            Complete your personalized Prakriti assessment to receive tailored dietary recommendations 
            based on ancient Ayurvedic wisdom combined with modern nutritional science.
          </p>
        </div>

        {/* Progress Indicator */}
        <ProgressIndicator 
          currentStep={currentStep}
          totalSteps={steps?.length}
          steps={steps}
        />

        {/* Step Content */}
        {currentStep === 1 && (
          <PersonalInfoForm
            formData={formData}
            onFormDataChange={setFormData}
            onNext={handlePersonalInfoNext}
            errors={errors}
          />
        )}

        {currentStep === 2 && currentQuestion && (
          <QuestionCard
            question={currentQuestion}
            selectedAnswer={selectedAnswer}
            onAnswerSelect={handleAnswerSelect}
            onNext={handleQuestionNext}
            onPrevious={handleQuestionPrevious}
            isFirst={currentQuestionIndex === 0}
            isLast={currentQuestionIndex === assessmentQuestions?.length - 1}
            canProceed={canProceedQuestion}
          />
        )}

        {currentStep === 3 && assessmentResult && (
          <ConstitutionResult
            result={assessmentResult}
            onStartDietGeneration={handleStartDietGeneration}
            onRetakeAssessment={handleRetakeAssessment}
          />
        )}

        {/* Help Section */}
        <div className="mt-12 bg-surface rounded-lg p-6 border border-border">
          <div className="flex items-start space-x-4">
            <Icon name="HelpCircle" size={24} className="text-accent flex-shrink-0 mt-1" />
            <div>
              <h3 className="font-heading font-semibold text-lg text-text-primary mb-2">
                Need Help with Your Assessment?
              </h3>
              <p className="text-text-secondary mb-4 leading-relaxed">
                Our Prakriti assessment is based on traditional Ayurvedic principles. Answer honestly 
                based on your natural tendencies, not temporary conditions. If you're unsure about 
                an answer, choose the option that best describes you most of the time.
              </p>
              <div className="flex flex-wrap gap-3">
                <Button variant="outline" size="sm" iconName="Book">
                  Learn About Doshas
                </Button>
                <Button variant="outline" size="sm" iconName="MessageCircle">
                  Contact Support
                </Button>
                <Button variant="outline" size="sm" iconName="Video">
                  Watch Tutorial
                </Button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PatientProfileBuilder;